/*
 * node_modules/mochitls — node:tls-shaped shim on top of mochitls.dll.
 *
 * Real Schannel TLS client: connect() opens a TCP socket, performs the
 * Schannel handshake with full certificate-chain + hostname validation
 * (default credentials, no manual validation), then write()/end() send and a
 * cooperative 10ms poll loop pumps decrypted 'data' events. createServer is
 * not supported (no TLS server).
 */

import { EventEmitter } from '../mochievents/index.js';
import { setTimeout as osSetTimeout, clearTimeout as osClearTimeout } from 'mbjs:os';
import * as native from '../../mochi_modules/mochitls/script/index.js';

function unsupported(name) {
    const err = new Error(`mochitls: ${name} is unavailable on MochiBerry runtime`);
    err.code = 'MOCHI_UNSUPPORTED';
    return err;
}

export class TLSSocket extends EventEmitter {
    constructor() {
        super();
        this.connecting = false;
        this.destroyed = true;
        this.readable = false;
        this.writable = false;
        this.encrypted = true;
        this.authorized = false;
        this.alpnProtocol = false;
        this._handle = -1;
        this._timer = null;
        this._bytesRead = 0;
        this._bytesWritten = 0;
    }

    async connect(port, host, cb) {
        if (typeof host === 'function') { cb = host; host = '127.0.0.1'; }
        host = host || '127.0.0.1';
        if (typeof cb === 'function') this.once('secureConnect', cb);
        this.connecting = true;
        try {
            const handle = await native.connect(String(host), Number(port));
            if (handle <= 0) {
                const msg = await native.lastError();
                queueMicrotask(() => this.emit('error', new Error('mochitls: connect to ' + host + ':' + port + ' failed: ' + msg)));
                return this;
            }
            this._handle = handle;
            this.connecting = false;
            this.destroyed = false;
            this.readable = true;
            this.writable = true;
            this.authorized = true;
            this.remoteAddress = host;
            this.remotePort = port;
            this.emit('secureConnect');
            this._startPolling();
        } catch (e) {
            queueMicrotask(() => this.emit('error', e));
        }
        return this;
    }

    _startPolling() {
        const poll = async () => {
            if (this.destroyed || this._handle < 0) return;
            let chunk = null;
            try { chunk = await native.read(this._handle, 65536); }
            catch (e) { this.destroy(); return; }
            if (chunk !== undefined && chunk !== null && chunk !== '') {
                const s = String(chunk);
                this._bytesRead += s.length;
                const bytes = new Uint8Array(s.length);
                for (let i = 0; i < s.length; i++) bytes[i] = s.charCodeAt(i) & 0xff;
                this.emit('data', bytes);
            }
            this._timer = osSetTimeout(poll, 10);
        };
        this._timer = osSetTimeout(poll, 10);
    }

    _writeData(data) {
        if (this.destroyed || this._handle < 0) return 0;
        const s = typeof data === 'string' ? data
            : (data instanceof Uint8Array ? Array.from(data, (b) => String.fromCharCode(b)).join('') : String(data));
        try {
            const n = native.write(this._handle, s);
            if (n > 0) this._bytesWritten += Number(n);
            return n;
        } catch (e) { return 0; }
    }

    write(data, cb) {
        const n = this._writeData(data);
        if (typeof cb === 'function') queueMicrotask(cb);
        return n !== 0;
    }

    end(data, cb) {
        if (data !== undefined && data !== null) this._writeData(data);
        if (this._timer) { osClearTimeout(this._timer); this._timer = null; }
        if (this._handle >= 0) {
            try { native.close(this._handle); } catch (e) {}
            this._handle = -1;
        }
        this.readable = false;
        this.writable = false;
        this.emit('end');
        this.emit('close');
        this.destroyed = true;
        if (typeof cb === 'function') queueMicrotask(cb);
        return this;
    }

    destroy(error) {
        if (this._timer) { osClearTimeout(this._timer); this._timer = null; }
        if (this._handle >= 0) {
            try { native.close(this._handle); } catch (e) {}
            this._handle = -1;
        }
        this.readable = false;
        this.writable = false;
        this.destroyed = true;
        if (error) this.emit('error', error);
        this.emit('close');
        return this;
    }

    setTimeout() { return this; }
    setNoDelay() { return this; }
    setKeepAlive() { return this; }
}

export function connect(options, cb) {
    const sock = new TLSSocket();
    if (typeof options === 'object' && options !== null) {
        sock.connect(options.port, options.host || '127.0.0.1', cb);
    } else {
        sock.connect(options, cb);
    }
    return sock;
}
export function createServer() { throw unsupported('tls.createServer'); }
export const DEFAULT_MIN_VERSION = 'TLSv1.2';
export const DEFAULT_MAX_VERSION = 'TLSv1.3';
export default { TLSSocket, connect, createServer, DEFAULT_MIN_VERSION, DEFAULT_MAX_VERSION };
